-- C11 / P11.9 — Books execution policy preserves normal-chat ownership, project-specific scope, portfolio-Agent exclusion, and Work publishing-only boundaries.
create table if not exists public.command_center_book_execution_policy_history (
 owner_id uuid not null references auth.users(id) on delete cascade,
 policy_event_id text not null check(btrim(policy_event_id)<>''), policy_id text not null check(btrim(policy_id)<>''), project_id text not null check(btrim(project_id)<>''), version integer not null check(version>0), portfolio_agent_auto_allowed boolean not null default false,
 normal_chat_scope text[] not null check(cardinality(normal_chat_scope)>0), work_scope text[] not null check(cardinality(work_scope)>0), brain_scope text[] not null default '{}'::text[], foundry_scope text[] not null default '{}'::text[], project_agent_scope text[] not null default '{}'::text[], source_refs text[] not null check(cardinality(source_refs)>0), observed_at timestamptz not null,
 primary key(owner_id,policy_event_id), unique(owner_id,policy_id,version),
 check(work_scope <@ array['publishing_account_browser_upload','previewer','submission','provider_account_bound_publishing']::text[])
);
create table if not exists public.command_center_book_execution_decision_history (
 owner_id uuid not null references auth.users(id) on delete cascade,
 decision_event_id text not null check(btrim(decision_event_id)<>''), request_id text not null check(btrim(request_id)<>''), project_id text not null check(btrim(project_id)<>''), book_id text, action text not null check(btrim(action)<>''), executor text not null check(executor in ('brain','foundry','project_agent','portfolio_agent','normal_chat','work')), exact_target_ref text not null, authorization_ref text, allowed boolean not null, reason text not null check(reason in ('allowed','portfolio_agent_excluded','outside_executor_scope','work_publishing_only','missing_exact_target','missing_protected_authorization')), observed_at timestamptz not null, evidence_refs text[] not null check(cardinality(evidence_refs)>0),
 primary key(owner_id,decision_event_id), unique(owner_id,request_id), check(book_id is null or btrim(book_id)<>''), check(authorization_ref is null or btrim(authorization_ref)<>'')
);
create or replace view public.command_center_book_execution_policies_current with (security_invoker=true) as select distinct on(owner_id,project_id) owner_id,policy_event_id,policy_id,project_id,version,portfolio_agent_auto_allowed,normal_chat_scope,work_scope,brain_scope,foundry_scope,project_agent_scope,source_refs,observed_at from public.command_center_book_execution_policy_history order by owner_id,project_id,version desc,observed_at desc;
create or replace function public.command_center_reject_book_execution_boundary_mutation() returns trigger language plpgsql set search_path to 'public' as $$ begin raise exception 'Book execution boundary evidence is immutable'; end $$;
drop trigger if exists command_center_book_execution_policy_immutable on public.command_center_book_execution_policy_history; create trigger command_center_book_execution_policy_immutable before update or delete on public.command_center_book_execution_policy_history for each row execute function public.command_center_reject_book_execution_boundary_mutation();
drop trigger if exists command_center_book_execution_decision_immutable on public.command_center_book_execution_decision_history; create trigger command_center_book_execution_decision_immutable before update or delete on public.command_center_book_execution_decision_history for each row execute function public.command_center_reject_book_execution_boundary_mutation();
alter table public.command_center_book_execution_policy_history enable row level security; alter table public.command_center_book_execution_decision_history enable row level security;
revoke all on table public.command_center_book_execution_policy_history,public.command_center_book_execution_decision_history from public,anon,authenticated; grant select,insert on table public.command_center_book_execution_policy_history,public.command_center_book_execution_decision_history to authenticated; grant select on table public.command_center_book_execution_policies_current to authenticated;
create policy p11_9_book_execution_policy_owner on public.command_center_book_execution_policy_history for all to authenticated using(owner_id=(select auth.uid()) and (select public.is_command_center_authorized())) with check(owner_id=(select auth.uid()) and (select public.is_command_center_authorized()));
create policy p11_9_book_execution_decision_owner on public.command_center_book_execution_decision_history for all to authenticated using(owner_id=(select auth.uid()) and (select public.is_command_center_authorized())) with check(owner_id=(select auth.uid()) and (select public.is_command_center_authorized()));
